#include "sr_p4_ev1.h"
const uint8_t sr_p4_ev1_xmas_extra_flags[8] = { 0x09, 0x2A, 0x31, 0x33, 0x4E, 0x4F, 0x59, 0x5A };

const uint8_t sr_p4_ev1_lost_continent_orb_flags[7] = { EVF_GRANDPALACE_GNOME_ORB_FLAG, EVF_GRANDPALACE_UNDINE_ORB_FLAG, EVF_GRANDPALACE_SYLPHID_ORB_FLAG, EVF_GRANDPALACE_SALAMANDO_ORB_FLAG, EVF_GRANDPALACE_LUMINA_ORB_FLAG, EVF_GRANDPALACE_SHADE_ORB_FLAG, EVF_GRANDPALACE_LUNA_ORB_FLAG };


int sr_p4_ev_new_game(struct sr_ctx *c) {
  /* //////////////////////////////////////////////////// */
  /* x400 - intro with the manafort backdrop and shit */
  /* //////////////////////////////////////////////////// */
  struct sr_bytes *newEvent400 = NULL;
  newEvent400 = sr_event_new(c, 0x400);
  sr_ev_incr_flag(c, newEvent400, EVF_DIALOGUE_NO_BORDER_FLAG);
  const char *goalType = sr_p4_ev1_wstr(c, "openWorldGoalShortName");
  int flammieDrumInLogic = sr_settings_get_bool(c->settings, "opFlammieDrumInLogic");
  /* ton of shit cut out in here */
  if (strcmp(goalType, "xmas2020") == 0 || strcmp(goalType, "xmas2020b") == 0 || flammieDrumInLogic) {
    /* enable menus as if we got the sword in vanilla */
    sr_ev_incr_flag(c, newEvent400, EVF_UI_DISPLAY_FLAG);
    sr_ev_incr_flag(c, newEvent400, EVF_UI_DISPLAY_FLAG);
    if (flammieDrumInLogic) {
      /* clear out the npcs */
      sr_ev_set_flag(c, newEvent400, EVF_POTOS_FLAG, 0xA);
    }
    /* run door 0x82 as the start door.  note that OpenWorldSupportingMapChanges changes this to one of a couple different */
    /* locations based on settings. */
    sr_ev_door(c, newEvent400, 0x82);
  }
  else if (!flammieDrumInLogic) {
    /* vanilla start door - start on the log */
    sr_ev_door(c, newEvent400, 0x00);
  }

  sr_ev_decr_flag(c, newEvent400, EVF_DIALOGUE_NO_BORDER_FLAG);
  sr_ev_jump(c, newEvent400, 0x106);
  sr_ev_end(c, newEvent400);
  return 1;
}

int sr_p4_ev_intro(struct sr_ctx *c) {
  const char *goalType = sr_p4_ev1_wstr(c, "openWorldGoalShortName");

  /* //////////////////////////////////////////////////// */
  /* x106 - waterfall intro */
  /* //////////////////////////////////////////////////// */
  struct sr_bytes *newEvent106 = NULL;
  newEvent106 = sr_event_new(c, 0x106);

  /* 1F03 - set state of world map for best flammie landings (with some mods) */
  sr_p4_ev1_add(c, newEvent106, 0x1F);
  sr_p4_ev1_add(c, newEvent106, 0x03);

  /* add starting gold if specified */
  int goldAmount = sr_settings_get_int(c->settings, "opStartGold");
  if (goldAmount > 0) {
    sr_p4_ev1_add(c, newEvent106, EVC_ADD_GOLD);
    sr_p4_ev1_add(c, newEvent106, (uint8_t)goldAmount);
    sr_p4_ev1_add(c, newEvent106, (uint8_t)(goldAmount >> 8));
  }

  /* add whichever intro script decides it's applicable */
  /* note these end the 0x106 event, so anything common should be added before this point */
  sr_p4_nested(c, "Event 0x106 - intro (xmas gift delivery)", sr_p4_ev_intro_gift);
  sr_p4_nested(c, "Event 0x106 - intro (xmas reindeer)", sr_p4_ev_intro_reindeer);
  sr_p4_nested(c, "Event 0x106 - intro (flammie drum in logic)", sr_p4_ev_intro_flammie);
  sr_p4_nested(c, "Event 0x106 & 0x101 - intro (waterfall)", sr_p4_ev_intro_waterfall);

  sr_p4_nested(c, "Event 0x107 - Initialization of event flags", sr_p4_ev_initial_flags);

  /* load 0xC0 into 7E00E3 to unlock both purelands and the purple continent on world map */
  sr_poke(c, 0x1EB93, 0xC0);
  /* and in saveram loading, too - LDA instead of AND */
  sr_poke(c, 0x2AA57, 0xA9);

  if (strcmp(goalType, "manatree") == 0 || strcmp(goalType, "xmas2020") == 0 || strcmp(goalType, "xmas2020b") == 0) {
    /* disable flying manafort, but keep purelands open */
    sr_poke(c, 0x2b115, 0x00);
  }

  /* short-circuit the 1F03 event so it doesn't do that mode 7 hover scene */
  sr_poke(c, 0x1EBA8, 0x60);
  sr_poke(c, 0x1EBA9, 0xEA);
  sr_poke(c, 0x1EBAA, 0xEA);
  sr_poke(c, 0x1EBAB, 0xEA);

  /* make the sword visible 0x10 00-0A */
  int mapNum = MAPNUM_RUSTYSWORD;
  int mapObjOffset = 0x80000 + sr_peek(c, 0x87000 + mapNum * 2) + (sr_peek(c, 0x87000 + mapNum * 2 + 1) << 8);
  mapObjOffset += 8;

  sr_poke(c, mapObjOffset + 8 * 0 + 0, 0x10);
  sr_poke(c, mapObjOffset + 8 * 0 + 1, 0x0A);
  return 1;
}

int sr_p4_ev_intro_flammie(struct sr_ctx *c) {
  if (!sr_settings_get_bool(c->settings, "opFlammieDrumInLogic")) {
    return 0;
  }
  if (strcmp(sr_p4_ev1_wstr(c, "openWorldGoalShortName"), "xmas2020") == 0 || strcmp(sr_p4_ev1_wstr(c, "openWorldGoalShortName"), "xmas2020b") == 0) {
    /* keep the christmas start text */
    return 0;
  }

  struct sr_bytes *eventData = sr_p4_ev1_event_get(c, 0x106);
  sr_p4_ev1_add(c, eventData, EVC_PLAY_SOUND);
  sr_p4_ev1_add(c, eventData, 0x01);
  sr_p4_ev1_add(c, eventData, 0x11);
  sr_p4_ev1_add(c, eventData, 0x12);
  sr_p4_ev1_add(c, eventData, 0x8f);

  sr_p4_ev1_auto_dialogue_box(c, eventData, sr_p4_ev1_word_wrap(c, "Starting here because flammie drum is in logic! Give it a second here it's got a lot to set up"), 0x0A);

  /* event 0x107 - initialize event flags */
  sr_ev_jsr(c, eventData, 0x107);

  /* -> event x103, the sword grab event */
  sr_ev_jump(c, eventData, 0x103);
  sr_ev_end(c, eventData);
  return 1;
}

